if (a >= b || precision <= 0.0 || max_iter == 0)
        throw std::invalid_argument("Invalid arguments for bisection method");

    double fa = f(a);
    double fb = f(b);

    if (fa * fb > 0.0)
        throw std::runtime_error("Function does not change sign over the interval");

    double c = a;
    unsigned int iter = 0;

    while ((b - a) / 2.0 > precision && iter < max_iter) {
        c = (a + b) / 2.0;
        double fc = f(c);

        if (fc == 0.0 || (b - a) / 2.0 < precision)
            break;

        if (fa * fc < 0.0) {
            b = c;
            fb = fc;
        } else {
            a = c;
            fa = fc;
        }

        iter++;
    }

    return c;
    // END_CODE

